// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, uint256 times) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 1 ether, 10 ether);
        times = bound(times, 1, 5);
        address depositor = address(0xABCD);
        vm.deal(depositor, amount * times);
        for (uint256 i = 0; i < times; i++) {
            vm.prank(depositor);
            (bool ok,) = address(c).call{value: amount}("");
            assertTrue(ok);
        }
        // General rule: after n successful deposits of any amount, the deposits
        // counter equals n — a faithful per-deposit record that C maintains and
        // the mutant (deleted increment) violates.
        assertTrue(c.depositsCount() == times);
    }
}
